package connect

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
)

// CreateConnector creates one connector from a configuration generated by the Gateway.
type CreateConnector interface {
	Execute(ctx context.Context, name string, config map[string]string) error
}

type createConnector struct {
	baseURL string
	client  *http.Client
}

func NewCreateConnector(baseURL string, client *http.Client) CreateConnector {
	return createConnector{baseURL: strings.TrimRight(baseURL, "/"), client: client}
}

// Execute posts the configuration; Connect echoes it in the response, which is discarded so it never travels on.
func (c createConnector) Execute(ctx context.Context, name string, config map[string]string) error {
	if c.baseURL == "" {
		return ErrConnectNotConfigured
	}
	if err := ValidateConnectorName(name); err != nil {
		return err
	}
	body, err := json.Marshal(struct {
		Name   string            `json:"name"`
		Config map[string]string `json:"config"`
	}{name, config})
	if err != nil {
		return fmt.Errorf("%w: %w", ErrInvalidConnectAction, err)
	}
	request, err := http.NewRequestWithContext(ctx, http.MethodPost, c.baseURL+"/connectors", bytes.NewReader(body))
	if err != nil {
		return fmt.Errorf("%w: %w", ErrConnectUnreachable, err)
	}
	request.Header.Set("Content-Type", "application/json")
	request.Header.Set("Accept", "application/json")
	response, err := c.client.Do(request)
	if err != nil {
		return fmt.Errorf("%w: %w", ErrConnectActionUnknown, err)
	}
	defer response.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(response.Body, 1<<20))
	switch {
	case response.StatusCode >= 200 && response.StatusCode < 300:
		return nil
	case response.StatusCode == http.StatusConflict:
		return ErrConnectorExists
	case response.StatusCode >= 400 && response.StatusCode < 500:
		return fmt.Errorf("%w: status %d", ErrConnectRejected, response.StatusCode)
	default:
		return fmt.Errorf("%w: status %d", ErrConnectUnreachable, response.StatusCode)
	}
}
